jsb-variables.script.js:
const updateStock = (initialStock, received, shipped) => {
  let stock = initialStock;
  stock += received;
  stock -= shipped;
  return stock;
};

jsb-strings.script.js:
function labelTopic(topic) {
  const tag = '[' + topic + ']';
  return tag;
}

jsb-number.script.js:
function sumWeights(firstText, secondText) {
  return Number(firstText) + Number(secondText);
}

jsb-template.script.js:
function seatMessage(roomName, seatsLeft) {
  return roomName + ' has ' + seatsLeft + ' seats left.';
}

jsb-arithmetic.script.js:
function printCost(pagePrice, pages, bindingFee) {
  const printing = pagePrice * pages;
  return printing + bindingFee;
}

jsb-remainder.script.js:
function ungroupedCount(volunteers, groupSize) {
  const fullGroups = Math.floor(volunteers / groupSize);
  return volunteers - fullGroups * groupSize;
}

jsb-compare.script.js:
function meetsScore(score, minimumScore) {
  return minimumScore <= score;
}

jsb-logical.script.js:
function canEnterHall(isOpen, hasTicket, hasStaffPass) {
  return (isOpen && hasTicket) || (isOpen && hasStaffPass);
}
